using System.Text.Json;
using ChartForgeX.Markup.Mermaid;
using ChartForgeX.Mermaid;
using ChartForgeX.Themes;
using ChartForgeX.VisualArtifacts;
using Microsoft.Playwright;
using Xunit;
namespace ChartForgeX.Tests;
[Trait("BrowserSuite","Compatibility")]
public sealed class SequencePresetAppearanceBrowserTests {
    [BrowserTheory] [InlineData(false,390)] [InlineData(true,390)] [InlineData(false,1100)] [InlineData(true,1100)]
    public async Task DirectAndFenceHostsPaintTheSameOmittedModePaletteBandsAndCompleteVectorCaptions(bool dark,int width) {
        var source=SequencePresetSourceFixture.Canonical();var options=new MermaidRenderOptions{Presentation=new MermaidPresentationOptions{ThemeMode=dark?VisualThemeMode.Dark:VisualThemeMode.Light,FontFamily=BrowserProofFonts.Family},Sequence=new MermaidSequenceRenderOptions{Width=width-32,Height=860}};var direct=MermaidRenderer.Render(source,options);Assert.False(direct.HasErrors);var fence=new MermaidVisualMarkupParser(options).Parse("```mermaid\n"+source+"\n```");Assert.Equal(direct.Diagnostics.Select(d=>d.Code),fence.Diagnostics.Select(d=>d.Code));
        foreach(var pair in new[]{("direct",direct.Artifact!),("fence",Assert.Single(fence.Artifacts))}) {
            var model=Assert.IsType<SequenceArtifact>(pair.Item2.Model);var prepared=SequencePreparedCompiler.PrepareDefault(model);Assert.Null(model.Participants[0].SurfaceShadow);Assert.NotNull(model.Participants[1].SurfaceShadow);Assert.Contains("<image",prepared.ToSvg());var html=pair.Item2.ToHtmlPage(new VisualArtifactRenderOptions{HtmlSizing=VisualArtifactHtmlSizing.PreserveSize});await using var session=await BrowserProofFonts.OpenAsync(html,width,1000);var page=session.Page;var observed=await page.EvaluateAsync<JsonElement>("""
                () => {const s=document.querySelector('svg'),frame=s.getBoundingClientRect();const groups=[...s.querySelectorAll('[data-cfx-role="sequence-participant"]')];return {heads:groups.map(g=>({id:g.getAttribute('data-cfx-source-id'),glyphs:g.querySelectorAll('[data-cfx-role="sequence-participant-glyph"]').length,fill:[...g.querySelectorAll('[fill]')].map(e=>getComputedStyle(e).fill),stroke:[...g.querySelectorAll('[stroke]')].map(e=>getComputedStyle(e).stroke)})),text:[...s.querySelectorAll('text')].map(t=>t.textContent),footers:s.querySelectorAll('[data-cfx-role="sequence-participant-footer"]').length,tabs:s.querySelectorAll('[data-cfx-role="sequence-fragment-tab"]').length,clip:[...s.querySelectorAll('text')].filter(t=>{const b=t.getBoundingClientRect();return b.width&&b.height&&(b.left<frame.left-1.5||b.top<frame.top-1.5||b.right>frame.right+1.5||b.bottom>frame.bottom+1.5)}).map(t=>t.textContent),scripts:s.querySelectorAll('script,foreignObject').length,overflow:document.documentElement.scrollWidth>innerWidth};}
                """);var stem="sequence-preset-"+pair.Item1+"-"+width+(dark?"-dark":"-light");var output=Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY");if(!string.IsNullOrWhiteSpace(output)){Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,stem+".mmd"),source);File.WriteAllText(Path.Combine(output,stem+".svg"),prepared.ToSvg());File.WriteAllBytes(Path.Combine(output,stem+".native.png"),prepared.ToPng());File.WriteAllText(Path.Combine(output,stem+".native.json"),prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeJson());File.WriteAllText(Path.Combine(output,stem+".observed.json"),observed.GetRawText());File.WriteAllText(Path.Combine(output,stem+".diagnostics.txt"),string.Join("\n",direct.Diagnostics.Select(d=>d.Message)));await page.ScreenshotAsync(new PageScreenshotOptions{Path=Path.Combine(output,stem+".browser.png"),FullPage=true});}
            Assert.Equal(new[]{"A","B"},observed.GetProperty("heads").EnumerateArray().Select(x=>x.GetProperty("id").GetString()));foreach(var text in new[]{"Review","Owner","Archive","Save","Stored","Audit","Retain audit facts"})Assert.Contains(observed.GetProperty("text").EnumerateArray(),e=>e.GetString()==text);Assert.All(observed.GetProperty("heads").EnumerateArray(),e=>Assert.True(e.GetProperty("glyphs").GetInt32()>0));Assert.Contains(observed.GetProperty("heads")[0].GetProperty("stroke").EnumerateArray(),e=>e.GetString()=="rgb(232, 121, 249)");Assert.Contains(observed.GetProperty("heads")[1].GetProperty("stroke").EnumerateArray(),e=>e.GetString()=="rgb(45, 212, 191)");Assert.Equal(2,observed.GetProperty("footers").GetInt32());Assert.Equal(1,observed.GetProperty("tabs").GetInt32());Assert.Empty(observed.GetProperty("clip").EnumerateArray());Assert.Equal(0,observed.GetProperty("scripts").GetInt32());Assert.False(observed.GetProperty("overflow").GetBoolean());Assert.Equal(pair.Item2.ToSvg(),prepared.ToSvg());InteractiveChartBrowser.AssertNoConsoleErrors(session);
        }
    }
}
internal static class SequencePresetSourceFixture {internal static string Canonical()=>File.ReadAllText(Path.Combine(TestRepository.Root,"Build","PackageConsumers","Adapters","sequence-preset-appearance.mmd"));}
